const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const point_bor = ee.Geometry.Point(31.55, 6.23);
    const aoi = point_bor.buffer(50000); // 50km buffer around Bor

    const date1 = '2019-12-06';
    const date2 = '2021-12-04';

    // 2. Data Acquisition & Processing Function
    const get_water_area = function(date_str, geometry) {
        const start_date = ee.Date(date_str).advance(-2, 'day');
        const end_date = ee.Date(date_str).advance(2, 'day');

        // Sentinel-2 Image Collection
        let collection = ee.ImageCollection('COPERNICUS/S2_SR')
            .filterBounds(geometry)
            .filterDate(start_date, end_date)
            .sort('CLOUDY_PIXEL_PERCENTAGE');

        let collection_size = collection.size().getInfo();
        if (collection_size === 0) {
            return {
                status: 'C1',
                message: `No S2 images found for ${date_str}.`
            };
        }

        const image = ee.Image(collection.first());

        // Cloud Masking using QA60 band
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

        // Calculate MNDWI and identify water pixels
        const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
        const water_pixels = mndwi.gt(0).updateMask(mask); // Water is where MNDWI > 0

        // Calculate the area of water
        const water_area = water_pixels.multiply(ee.Image.pixelArea())
            .reduceRegion({
                reducer: ee.Reducer.sum(),
                geometry: geometry,
                scale: 1000,
                maxPixels: 1e9
            });

        // Get pixel count for validation
        const pixel_count_info = water_pixels.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: geometry,
            scale: 1000,
            maxPixels: 1e9
        }).get('MNDWI').getInfo();

        if (pixel_count_info === null || pixel_count_info === 0) {
            return {
                status: 'C2',
                message: `No valid water pixels for ${date_str}.`,
                cloud_percent: image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo()
            };
        }

        const area_sqkm = ee.Number(water_area.get('MNDWI')).divide(1e6).getInfo();

        if (area_sqkm === null) {
             return {
                status: 'C3',
                message: `Area calculation failed for ${date_str}.`
            };
        }

        return {
            status: 'OK',
            area: area_sqkm,
            pixels: pixel_count_info,
            cloud_percent: image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo(),
            date: image.date().format('YYYY-MM-dd').getInfo()
        };
    };

    // 3. Perform Analysis for both dates
    const result_2019 = get_water_area(date1, aoi);
    if (result_2019.status !== 'OK') {
        console.log(`2019 Analysis failed: ${result_2019.message}`);
        console.log(result_2019.status);
        return;
    }

    const result_2021 = get_water_area(date2, aoi);
    if (result_2021.status !== 'OK') {
        console.log(`2021 Analysis failed: ${result_2021.message}`);
        console.log(result_2021.status);
        return;
    }

    // 4. Evidence and Comparison
    console.log(`2019-12-06 (Image date: ${result_2019.date})`);
    console.log(`Water Extent: ${result_2019.area.toFixed(2)} sqkm`);
    console.log(`Valid Pixels: ${result_2019.pixels}, Cloud Cover: ${result_2019.cloud_percent.toFixed(2)}%`);

    console.log(`2021-12-04 (Image date: ${result_2021.date})`);
    console.log(`Water Extent: ${result_2021.area.toFixed(2)} sqkm`);
    console.log(`Valid Pixels: ${result_2021.pixels}, Cloud Cover: ${result_2021.cloud_percent.toFixed(2)}%`);

    if (result_2021.area > result_2019.area) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error('An error occurred during the analysis.');
    console.error(err);
    console.log('D');
});
